parameters.jsCode:
const body = $('Webhook').first().json.body ?? {};

const hallTicket = String(body.hallTicket ?? '')
  .trim()
  .toUpperCase();

const pin = String(body.pin ?? '').trim();
const question = String(body.question ?? '').trim();

if (!hallTicket || !pin || !question) {
  return [{
    json: {
      valid: false,
      message: 'Hall ticket, PIN and question are required.'
    }
  }];
}

const match = hallTicket.match(/^DEMO2026(\d{3})$/);
const number = match ? Number(match[1]) : 0;
const expectedPin = String(1000 + number);

if (!match || number < 1 || number > 30 || pin !== expectedPin) {
  return [{
    json: {
      valid: false,
      message: 'Invalid hall ticket or PIN.'
    }
  }];
}

const subjects = [
  'Programming',
  'Mathematics',
  'Database Systems',
  'Computer Networks',
  'Operating Systems'
];

const marks = [];

for (let sem = 1; sem <= 6; sem++) {
  for (let j = 0; j < subjects.length; j++) {
    const internal = 15 + ((hallTicket.length + sem + j * 3) % 11);
    const external = 25 + ((number + sem * 7 + j * 9) % 51);
    const total = internal + external;

    marks.push({
      semester: sem,
      subjectCode: `S${sem}0${j + 1}`,
      subjectName: subjects[j],
      internalMarks: internal,
      externalMarks: external,
      totalMarks: total,
      maxMarks: 100,
      result: total >= 40 ? 'PASS' : 'FAIL'
    });
  }
}

const agentInput = `
You are RevalAI, a student-friendly academic result assistant.

Student: Demo Student ${number}
Hall ticket: ${hallTicket}
Question: ${question}

Demo result records:
${JSON.stringify(marks)}

Rules:
- Answer only from the supplied records.
- Explain marks clearly and mention semester and subject.
- Never invent official grades, revaluation deadlines, fees, or eligibility.
- These are synthetic demo marks, not official university results.
- If the requested information is unavailable, say so.
- Be concise and helpful.
`;

return [{
  json: {
    valid: true,
    hallTicket,
    studentName: `Demo Student ${number}`,
    question,
    agentInput
  }
}];

parameters.responseBody:
={{ {
  success: false,
  message: $json.message || 'Invalid hall ticket or PIN.'
} }}
